style.css:
@-moz-document domain("neetprep.com") {
/* Hide the default NeetPrep logo */
    img[src*="logo"], .site-logo, .header-logo {
        visibility: hidden !important;
        opacity: 0 !important;
        width: 0px !important;
        height: 0px !important;
    }

    /* Replace logo with a Pixar doctor image */
    header::before {
        content: "";
        display: block;
        width: 200px;  /* Adjust size */
        height: 80px;  /* Adjust size */
        background: url('https://i.imgur.com/G6MxPAv.png') no-repeat center center;  /* Replace with a Pixar doctor image URL */
        background-size: contain;
        position: absolute;
        top: 10px;
        left: 20px;
        z-index: 9999;
    }
}
